local _, WFJ = ...
WFJ.Data.add("book", {
  ["eb12dd82b3e45a32"] = { "Gioisci della tua nuova condizione di non morto e usa i tuoi poteri per ripulire il mondo da coloro che vorrebbero vederci estirpati. Anche se i nostri nemici sono legioni, li distruggeremo con la fiamma e con l'ombra.\n\nQuando vorrai che ti insegni le vie dell'oscurità e dell'evocazione, mi troverai nella vecchia chiesa di ⟦Deathknell=Albamorta⟧.\n\n-Maximillion, istruttore degli stregoni.", "." },
  ["eb2bcc8c148601b4"] = { "Uldaman, giorno 6\n\n...una fame terribile. Ho finito le provviste e a questo punto considererei un banchetto anche del pane ammuffito. Ho visto la testa di un trogg trasformarsi in una succosa bistecca proprio davanti ai miei occhi...", "." },
  ["eb3d3c23e35078e4"] = { "Riscosse alcuni vecchi debiti con gli ⟦Highborne=Alti Nobili⟧ e attirò i naga serpentini fuori dai loro oscuri covi sottomarini. Guidati dall'astuta strega Lady Vashj, i naga aiutarono Illidan a raggiungere le Broken Isles, dove si diceva si trovasse la tomba di Sargeras.", "." },
  ["eb42aae525bc550e"] = { "Sael'ah, ti scrivo da amico. Spero che questo sigillo ti trovi in buona salute. Mi è stato chiesto di offrirti i miei servigi. Anch'io mi trovo a ⟦Shadowglen=Vallombra⟧, nel grande albero di Aldrassil, e volevo farti sapere che, se ti serve un addestramento, puoi venire a cercarmi.\n\nIn questi tempi incerti, ho ritenuto prudente che chi si occupa di furtività resti ancora più vicino agli altri del mestiere. Come potremmo altrimenti proteggere Teldrassil e le nostre usanze?\n\nCercami quando puoi.\n\n-Frahun Shadewhisper, istruttore dei ladri", "." },
  ["ebd91704f2e9e0c5"] = { "PRIMO GIORNO\n\nOggi l'apprendista e io siamo arrivati nella ⟦Coldridge Valley=Valle Crestafredda⟧. Il viaggio attraverso la caverna è stato per lo più tranquillo. Ci siamo accampati a buona distanza dalla grotta in cui, ci hanno detto, si sono radunati i troll.\n\nSECONDO GIORNO\n\nQuei maledetti lupi che ululavano mi hanno tenuto sveglio quasi tutta la notte.\n\nFra qualche giorno avrò abiti nuovi di pelle di lupo.\n\nOggi il ragazzo si è scontrato con un trogg, ha lottato e", "." },
  ["ebdff53c80eae7a2"] = { "I nostri colpi sparati in fretta bastarono a permettere a Barnil di fuggire. Barnil ridiscese la collina arrancando e si riunì al gruppo. Ci precipitammo nella giungla, con un branco di feroci Lashtail Raptor che seguiva ogni nostra mossa.\n\nI cacciatori ora erano le prede.", "." },
})
